def cells(g):
    h=len(g);w=len(g[0])
    sr=[r for r in range(h) if all(x==8 for x in g[r])]
    sc=[c for c in range(w) if all(g[r][c]==8 for r in range(h))]
    return sr,sc

def transform(g):
    h,w=len(g),len(g[0])
    sr,sc=cells(g)
    out=[row[:] for row in g]
    # cell boundaries
    rb=[-1]+sr+[h]; cb=[-1]+sc+[w]
    def cellid(r,c):
        ri=sum(1 for x in rb[1:-1] if r>x)-1
        ci=sum(1 for x in cb[1:-1] if c>x)-1
        return ri,ci
    marks={}
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,8):
                marks.setdefault(g[r][c],[]).append(cellid(r,c))
    fills={}
    for col,ps in marks.items():
        for i in range(len(ps)):
            for j in range(i+1,len(ps)):
                (r1,c1),(r2,c2)=ps[i],ps[j]
                if r1==r2:
                    for ci in range(min(c1,c2),max(c1,c2)+1): fills.setdefault((r1,ci),set()).add(col)
                if c1==c2:
                    for ri in range(min(r1,r2),max(r1,r2)+1): fills.setdefault((ri,c1),set()).add(col)
    for (ri,ci),cols in fills.items():
        color=6 if len(cols)>1 else cols.pop()
        for r in range(rb[ri]+1,rb[ri+1]):
            for c in range(cb[ci]+1,cb[ci+1]):
                out[r][c]=color
    return out
